/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field LastLogNum.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustDirectDebitMandateLastLogNum extends GUPPricingAttributeCustDirectDebitMandate implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, LastLogNum);
}

    public Set getAllowedValues()
    {
        var                    ret = new Set(Types::Integer);
        CustDirectDebitMandate custDirectDebitMandate;

        while select custDirectDebitMandate
            group by LastLogNum
        {
            if (! ret.in(custDirectDebitMandate.LastLogNum))
            {
                ret.add(custDirectDebitMandate.LastLogNum);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, LastLogNum));
        qbr.value(queryValue(_value));
    }
